const responseText = $input.item.json.choices[0].message.content;
const rawJson = responseText.replace(/```json\n?/gi, '').replace(/```/g, '').trim();
const parsed = JSON.parse(rawJson);

return {
  title: parsed.title,
  headline: parsed.headline,
  subline: parsed.subline,
  designPrompt: parsed.designPrompt
};

const { title, headline, subline, designPrompt } = $input.item.json;
const keys = [
  "infip-2bb032bd", "infip-5350e2b6", "infip-744117e5", "infip-b005d12c", "infip-e6ac682a", "infip-ac628e9f", "infip-2fcc7019", "infip-b058c62b", "infip-d1302957", "infip-3642c084", "infip-523fda1b", "infip-c0e6a9b5", "infip-ed3aaacb", "infip-9aa99cdb", "infip-17379f55", "infip-6b4a3ab4", "infip-5bdc6d7d", "infip-a32b9b2f", "infip-9d05a08f", "infip-be7dd422", "infip-9ff0efaa", "infip-fa216627", "infip-41cbfaa9", "infip-3b87ee6f", "infip-e609470f", "infip-86dc3b16", "infip-d112da9a", "infip-527ccd05", "infip-dc0cef3f", "infip-2bb032bd", "infip-5350e2b6", "infip-744117e5", "infip-b005d12c", "infip-4afc2039", "infip-c322704f", "infip-3642c084", "infip-3dd59b1f", "infip-d8cdc10b", "infip-1e3f796f", "infip-77c9ba18", "infip-f1bf735d", "infip-9d05a08f", "infip-c8e39b24", "infip-8a98801e", "infip-2b40ba53", "infip-5b95d2b3", "infip-d1302957", "infip-e30fc0ea", "infip-ef0a0c21", "infip-68e9200d", "infip-6a801c65", "infip-55c92743", "infip-36fd29ab", "infip-b98ee253", "infip-abb8260d", "infip-94140f27", "infip-9db76de0", "infip-ee8c4b91", "infip-38e7bcc4", "infip-6d86d5f6", "infip-8357e5dc", "infip-6cf39dfc", "infip-04bf8c3a", "infip-c488dc9d", "infip-129aefd5", "infip-91900813"
];

const buildPrompt = (bg) => `You are generating a flat 2D digital graphic file — NOT a poster, NOT a mockup... Every pixel from corner to corner is part of the design itself. The ONLY text permitted in the image: 1. "DARSY" — top-right corner. 2. Headline: "${headline}" — bold, large display type. ${subline ? `3. Subline: "${subline}"` : ""}. COLOR PALETTE: Grayscale subject, Accent green (#3aaa6a). Background: strictly ${bg}. Topic: ${title}. Scene: ${designPrompt}. Editorial fashion photography style. Asymmetric layout. No center subject. No mockup frames. NO PHYSICAL POSTER INSIDE IMAGE.`.trim();

let urls = [];
const bgs = ['pure white (#ffffff)', 'solid green (#3aaa6a)'];

for (const bg of bgs) {
  for (let i = 0; i < 3; i++) {
    const randomKey = keys[Math.floor(Math.random() * keys.length)];
    try {
      const res = await fetch('https://api.infip.pro/v1/images/generations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${randomKey}` },
        body: JSON.stringify({ model: 'img3', prompt: buildPrompt(bg), n: 3, size: '1024x1024' })
      });
      let data = await res.json();
      if (data.data) { 
        urls.push(...data.data.map(d => d.url)); 
        break; 
      }
    } catch(e) {}
  }
}

// Fallback
if (urls.length === 0) {
  for(let i=0; i<6; i++) urls.push(`https://image.pollinations.ai/prompt/${encodeURIComponent(buildPrompt(i<3 ? 'white':'green'))}?width=1024&height=1024&nologo=true&seed=${Math.floor(Math.random()*1000000)}`);
}

return { data: urls.map(url => ({ url, title })) };
